package main

import (
	"fmt"

	"golang.org/x/time/rate"
)

func main() {
	// Token bucket: 10 req/s steady, but absorbs bursts up to 20.
	lim := rate.NewLimiter(rate.Limit(10), 20)

	allowed := 0
	for i := 0; i < 25; i++ { // 25 requests arrive back-to-back
		if lim.Allow() {
			allowed++
		}
	}
	// The full burst of 20 is admitted; the rest are shed.
	fmt.Println("admitted in burst:", allowed)
}
// Output:
// admitted in burst: 20

// Sliding-window log: allow at most `limit` events in any `window`.
type SlidingLog struct {
	limit  int
	window time.Duration
	events []time.Time // allowed timestamps, oldest first
}

func (l *SlidingLog) Allow(now time.Time) bool {
	cutoff := now.Add(-l.window)
	// Drop timestamps that have slid out of the window.
	i := 0
	for i < len(l.events) && !l.events[i].After(cutoff) {
		i++
	}
	l.events = l.events[i:]
	if len(l.events) >= l.limit {
		return false // window is full
	}
	l.events = append(l.events, now)
	return true
}
// Output: rejects the (limit+1)-th event within any rolling window

package main

import (
	"context"
	"fmt"
	"time"

	"golang.org/x/time/rate"
)

func main() {
	lim := rate.NewLimiter(rate.Limit(2), 2) // 2/s, burst 2, starts full

	fmt.Println(lim.Allow()) // true  (token 1)
	fmt.Println(lim.Allow()) // true  (token 2)
	fmt.Println(lim.Allow()) // false (bucket empty)

	start := time.Now()
	_ = lim.Wait(context.Background()) // blocks ~0.5s for a refill
	fmt.Printf("waited ~%.0fms\n", time.Since(start).Seconds()*1000)
}
// Output:
// true
// true
// false
// waited ~500ms

type Limiters struct {
	mu      sync.Mutex
	clients map[string]*rate.Limiter
}

func (l *Limiters) get(key string) *rate.Limiter {
	l.mu.Lock()
	defer l.mu.Unlock()
	lim, ok := l.clients[key]
	if !ok {
		lim = rate.NewLimiter(rate.Limit(10), 20) // per-client budget
		l.clients[key] = lim
	}
	return lim
}

func (l *Limiters) Allow(clientKey string) bool {
	return l.get(clientKey).Allow()
}
// Output: each API key gets its own independent 10 req/s bucket

// Atomic fixed-window limiter: INCR + set TTL on first hit, in one round trip.
const incrExpire = `
local n = redis.call('INCR', KEYS[1])
if n == 1 then
	redis.call('EXPIRE', KEYS[1], ARGV[1])
end
return n`

func allow(ctx context.Context, rdb *redis.Client, key string, limit, window int) (bool, error) {
	n, err := rdb.Eval(ctx, incrExpire, []string{key}, window).Int()
	if err != nil {
		return false, err // decide fail-open vs fail-closed here
	}
	return n <= limit, nil
}
// Output: all replicas share one counter, so the global limit holds across the fleet

func handler(w http.ResponseWriter, r *http.Request, lim *rate.Limiter) {
	res := lim.Reserve()
	if !res.OK() || res.Delay() > 0 {
		delay := res.Delay()
		res.Cancel() // rejecting, not waiting: return the token
		secs := int(math.Ceil(delay.Seconds()))
		if secs < 1 {
			secs = 1
		}
		w.Header().Set("Retry-After", strconv.Itoa(secs))
		http.Error(w, "rate limit exceeded", http.StatusTooManyRequests)
		return
	}
	fmt.Fprintln(w, "ok")
}
// Output: over-quota requests get 429 with e.g. Retry-After: 1

