package solution

import (
	"testing"
	"time"
)

func TestLimiter(t *testing.T) {
	// Controllable clock: tests advance `clock` instead of sleeping.
	clock := time.Unix(0, 0)
	now := func() time.Time { return clock }

	// rate = 2 tokens/sec, burst = 3 (starts full).
	l := NewLimiter(2, 3, now)

	// Three immediate Allows drain the full bucket.
	for i := 0; i < 3; i++ {
		if !l.Allow() {
			t.Fatalf("burst token %d: want true, got false", i+1)
		}
	}
	// Bucket is empty now: the next Allow must fail.
	if l.Allow() {
		t.Fatal("empty bucket: want false, got true")
	}

	// Advance 1 second: at 2 tokens/sec, 2 tokens refill.
	clock = clock.Add(time.Second)
	if !l.Allow() {
		t.Fatal("after 1s, token 1: want true")
	}
	if !l.Allow() {
		t.Fatal("after 1s, token 2: want true")
	}
	if l.Allow() {
		t.Fatal("after 1s, token 3: want false (only 2 refilled)")
	}

	// Advance 10s: refill must cap at burst (3), not 20.
	clock = clock.Add(10 * time.Second)
	for i := 0; i < 3; i++ {
		if !l.Allow() {
			t.Fatalf("after 10s idle, token %d: want true", i+1)
		}
	}
	if l.Allow() {
		t.Fatal("after 10s idle: want false (capped at burst=3)")
	}
}

